445:    /**
446:     * Initiate state change from CPMS directly.
447:     */
448:    private void onApPowerStateChange(int apState,
449:            @CarPowerManager.CarPowerState int carPowerStateListenerState) {
450:        CpmsState newState = new CpmsState(apState, carPowerStateListenerState,
451:                /* canPostpone= */ false);
452:        synchronized (mLock) {
453:            if (newState.mState == CpmsState.WAIT_FOR_FINISH) {
454:                // We are ready to shut down. Suppress this transition if
455:                // there is a request to cancel the shutdown (WAIT_FOR_VHAL).
456:                for (int idx = 0; idx < mPendingPowerStates.size(); idx++) {
457:                    if (mPendingPowerStates.get(idx).mState == CpmsState.WAIT_FOR_VHAL) {
458:                        // Completely ignore this WAIT_FOR_FINISH
459:                        return;
460:                    }
461:                }
462:            }
463:            mPendingPowerStates.addFirst(newState);
464:            mLock.notify();
465:        }
466:        mHandler.handlePowerStateChange();
467:    }
