469:    private void doHandlePowerStateChange() {
470:        CpmsState state;
471:        synchronized (mLock) {
472:            state = mPendingPowerStates.pollFirst();
473:            if (state == null) {
474:                Slogf.w(TAG, "No more power state to process");
475:                return;
476:            }
477:            Slogf.i(TAG, "doHandlePowerStateChange: newState=%s", state.name());
478:            if (!needPowerStateChangeLocked(state)) {
479:                // We may need to process the pending power state request.
480:                if (!mPendingPowerStates.isEmpty()) {
481:                    Slogf.i(TAG, "There is a pending power state change request. requesting the "
482:                            + "processing...");
483:                    mHandler.handlePowerStateChange();
484:                }
485:                return;
486:            }
487:            // now real power change happens. Whatever was queued before should be all cancelled.
488:            mPendingPowerStates.clear();
489:            cancelWaitingForCompletion();
490:            mCurrentState = state;
491:        }
492:        mHandler.cancelProcessingComplete();
493:
494:        Slogf.i(TAG, "setCurrentState %s", state);
495:        CarStatsLogHelper.logPowerState(state.mState);
496:        EventLogHelper.writeCarPowerManagerStateChange(state.mState);
497:        switch (state.mState) {
498:            case CpmsState.WAIT_FOR_VHAL:
499:                handleWaitForVhal(state);
500:                break;
501:            case CpmsState.ON:
502:                handleOn();
503:                break;
504:            case CpmsState.SHUTDOWN_PREPARE:
505:                handleShutdownPrepare(state);
506:                break;
507:            case CpmsState.SIMULATE_SLEEP:
508:            case CpmsState.SIMULATE_HIBERNATION:
509:                simulateShutdownPrepare(state);
510:                break;
511:            case CpmsState.WAIT_FOR_FINISH:
512:                handleWaitForFinish(state);
513:                break;
514:            case CpmsState.SUSPEND:
515:                // Received FINISH from VHAL
516:                handleFinish();
517:                break;
518:            default:
519:                // Illegal state
520:                // TODO(b/202414427): Add handling of illegal state
521:                break;
522:        }
523:    }
