525:    private void handleWaitForVhal(CpmsState state) {
526:        @CarPowerManager.CarPowerState int carPowerStateListenerState =
527:                state.mCarPowerStateListenerState;
528:        // TODO(b/177478420): Restore Wifi, Audio, Location, and Bluetooth, if they are artificially
529:        // modified for S2R.
530:        mSilentModeHandler.querySilentModeHwState();
531:        sendPowerManagerEvent(carPowerStateListenerState, INVALID_TIMEOUT);
532:        // Inspect CarPowerStateListenerState to decide which message to send via VHAL
533:        switch (carPowerStateListenerState) {
534:            case CarPowerManager.STATE_WAIT_FOR_VHAL:
535:                mHal.sendWaitForVhal();
536:                break;
537:            case CarPowerManager.STATE_SHUTDOWN_CANCELLED:
538:                synchronized (mLock) {
539:                    mShutdownOnNextSuspend = false; // This cancels the "NextSuspend"
540:                }
541:                mHal.sendShutdownCancel();
542:                break;
543:            case CarPowerManager.STATE_SUSPEND_EXIT:
544:                mHal.sendSleepExit();
545:                break;
546:            case CarPowerManager.STATE_HIBERNATION_EXIT:
547:                mHal.sendHibernationExit();
