1843:    // Send the command to enter Suspend to RAM.
1844:    // If the command is not successful, try again with an exponential back-off.
1845:    // If it fails repeatedly, send the command to shut down.
1846:    // If we decide to go to a different power state, abort this retry mechanism.
1847:    // Returns true if we successfully suspended.
1848:    private boolean suspendWithRetries() {
1849:        boolean isDeepSleep;
1850:        synchronized (mLock) {
1851:            isDeepSleep = (mActionOnFinish == ACTION_ON_FINISH_DEEP_SLEEP);
1852:        }
1853:
1854:        String suspendTarget = isDeepSleep ? "Suspend-to-RAM" : "Suspend-to-Disk";
1855:        long retryIntervalMs = INITIAL_SUSPEND_RETRY_INTERVAL_MS;
1856:        long totalWaitDurationMs = 0;
1857:        while (true) {
1858:            Slogf.i(TAG, "Entering %s", suspendTarget);
1859:            boolean suspendSucceeded = isDeepSleep ? mSystemInterface.enterDeepSleep()
1860:                    : mSystemInterface.enterHibernation();
1861:
1862:            if (suspendSucceeded) {
1863:                return true;
1864:            }
1865:            if (totalWaitDurationMs >= mMaxSuspendWaitDurationMs) {
1866:                break;
1867:            }
1868:            // We failed to suspend. Block the thread briefly and try again.
1869:            synchronized (mLock) {
1870:                if (mPendingPowerStates.isEmpty()) {
1871:                    Slogf.w(TAG, "Failed to Suspend; will retry after %dms", retryIntervalMs);
1872:                    try {
1873:                        mLock.wait(retryIntervalMs);
1874:                    } catch (InterruptedException ignored) {
1875:                        Thread.currentThread().interrupt();
1876:                    }
1877:                    totalWaitDurationMs += retryIntervalMs;
1878:                    retryIntervalMs = Math.min(retryIntervalMs * 2, MAX_RETRY_INTERVAL_MS);
1879:                } else {
1880:                    // Check for a new power state now, before going around the loop again.
1881:                    CpmsState state = mPendingPowerStates.peekFirst();
1882:                    if (state != null && needPowerStateChangeLocked(state)) {
1883:                        Slogf.i(TAG, "Terminating the attempt to %s", suspendTarget);
1884:                        return false;
1885:                    }
1886:                }
1887:            }
1888:        }
1889:        // Too many failures trying to suspend. Shut down.
1890:        Slogf.w(TAG, "Could not %s after %dms long trial. Shutting down.", suspendTarget,
1891:                totalWaitDurationMs);
1892:        mSystemInterface.shutdown();
1893:        return false;
1894:    }
