331:    @VisibleForTesting
332:    void readPowerPolicyFromXml(InputStream stream) throws PolicyXmlException,
333:            XmlPullParserException, IOException {
334:        XmlPullParser parser = Xml.newPullParser();
335:        parser.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES, NAMESPACE != null);
336:        parser.setInput(stream, null);
337:
338:        // Ensure <powerPolicy> is the root
339:        parser.nextTag();
340:        parser.require(START_TAG, NAMESPACE, TAG_POWER_POLICY);
341:        // Check version
342:        String version = parser.getAttributeValue(NAMESPACE, ATTR_VERSION);
343:        if (!VALID_VERSIONS.contains(version)) {
344:            throw new PolicyXmlException("invalid XML version: " + version);
345:        }
346:
347:        ArrayMap<String, CarPowerPolicy> registeredPolicies = new ArrayMap<>();
348:        ArrayMap<String, SparseArray<String>> policyGroups = new ArrayMap<>();
349:        CarPowerPolicy systemPolicyOverride = null;
350:
351:        int type;
352:        while ((type = parser.next()) != END_DOCUMENT && type != END_TAG) {
353:            if (type != START_TAG) continue;
354:            switch (parser.getName()) {
355:                case TAG_POLICIES:
356:                    registeredPolicies = parsePolicies(parser, true);
357:                    break;
358:                case TAG_POLICY_GROUPS:
359:                    policyGroups = parsePolicyGroups(parser);
360:                    break;
361:                case TAG_SYSTEM_POLICY_OVERRIDES:
362:                    systemPolicyOverride = parseSystemPolicyOverrides(parser);
363:                    break;
364:                default:
365:                    throw new PolicyXmlException("unknown tag: " + parser.getName() + " under "
366:                            + TAG_POWER_POLICY);
367:            }
368:        }
369:        validatePolicyGroups(policyGroups, registeredPolicies);
370:
371:        mRegisteredPowerPolicies = registeredPolicies;
372:        mPolicyGroups = policyGroups;
373:        reconstructSystemPowerPolicy(systemPolicyOverride);
374:    }
