376:    private ArrayMap<String, CarPowerPolicy> parsePolicies(XmlPullParser parser,
377:            boolean includeOtherComponents) throws PolicyXmlException, XmlPullParserException,
378:            IOException {
379:        ArrayMap<String, CarPowerPolicy> policies = new ArrayMap<>();
380:        int type;
381:        while ((type = parser.next()) != END_DOCUMENT && type != END_TAG) {
382:            if (type != START_TAG) continue;
383:            if (TAG_POLICY.equals(parser.getName())) {
384:                String policyId = parser.getAttributeValue(NAMESPACE, ATTR_ID);
385:                if (policyId == null || policyId.equals("")) {
386:                    throw new PolicyXmlException("no |" + ATTR_ID + "| attribute of |" + TAG_POLICY
387:                            + "| tag");
388:                }
389:                if (includeOtherComponents && isSystemPowerPolicy(policyId)) {
390:                    throw new PolicyXmlException("Policy ID should not start with "
391:                            + SYSTEM_POWER_POLICY_PREFIX);
392:                }
393:                policies.put(policyId, parsePolicy(parser, policyId, includeOtherComponents));
394:            } else {
395:                throw new PolicyXmlException("unknown tag: " + parser.getName() + " under "
396:                        + TAG_POLICIES);
397:            }
398:        }
399:        return policies;
400:    }
