402:    private ArrayMap<String, SparseArray<String>> parsePolicyGroups(XmlPullParser parser) throws
403:            PolicyXmlException, XmlPullParserException, IOException {
404:        ArrayMap<String, SparseArray<String>> policyGroups = new ArrayMap<>();
405:        int type;
406:        while ((type = parser.next()) != END_DOCUMENT && type != END_TAG) {
407:            if (type != START_TAG) continue;
408:            if (TAG_POLICY_GROUP.equals(parser.getName())) {
409:                String groupId = parser.getAttributeValue(NAMESPACE, ATTR_ID);
410:                if (groupId == null || groupId.equals("")) {
411:                    throw new PolicyXmlException("no |" + ATTR_ID + "| attribute of |"
412:                            + TAG_POLICY_GROUP + "| tag");
413:                }
414:                policyGroups.put(groupId, parsePolicyGroup(parser));
415:            } else {
416:                throw new PolicyXmlException("unknown tag: " + parser.getName() + " under "
417:                        + TAG_POLICY_GROUPS);
418:            }
419:        }
420:        return policyGroups;
421:    }
