423:    @Nullable
424:    private CarPowerPolicy parseSystemPolicyOverrides(XmlPullParser parser) throws
425:            PolicyXmlException, XmlPullParserException, IOException {
426:        ArrayMap<String, CarPowerPolicy> systemOverrides = parsePolicies(parser, false);
427:        int numOverrides = systemOverrides.size();
428:        if (numOverrides == 0) {
429:            return null;
430:        }
431:        if (numOverrides > 1) {
432:            throw new PolicyXmlException("only one system power policy is supported: "
433:                    + numOverrides + " system policies exist");
434:        }
435:        CarPowerPolicy policyOverride =
436:                systemOverrides.get(POWER_POLICY_ID_NO_USER_INTERACTION);
437:        if (policyOverride == null) {
438:            throw new PolicyXmlException("system power policy id should be "
439:                    + POWER_POLICY_ID_NO_USER_INTERACTION);
440:        }
441:        Set<Integer> visited = new ArraySet<>();
442:        checkSystemPowerPolicyComponents(policyOverride.getEnabledComponents(), visited);
443:        checkSystemPowerPolicyComponents(policyOverride.getDisabledComponents(), visited);
444:        return policyOverride;
445:    }
