447:    private CarPowerPolicy parsePolicy(XmlPullParser parser, String policyId,
448:            boolean includeOtherComponents) throws PolicyXmlException, XmlPullParserException,
449:            IOException {
450:        SparseBooleanArray components = new SparseBooleanArray();
451:        String behavior = POWER_ONOFF_UNTOUCHED;
452:        boolean otherComponentsProcessed = false;
453:        int type;
454:        while ((type = parser.next()) != END_DOCUMENT && type != END_TAG) {
455:            if (type != START_TAG) continue;
456:            if (TAG_COMPONENT.equals(parser.getName())) {
457:                String id = parser.getAttributeValue(NAMESPACE, ATTR_ID);
458:                int powerComponent = toPowerComponent(id, true);
459:                if (powerComponent == INVALID_POWER_COMPONENT) {
460:                    throw new PolicyXmlException("invalid value(" + id + ") in |" + ATTR_ID
461:                            + "| attribute of |" + TAG_COMPONENT + "| tag");
462:                }
463:                if (components.indexOfKey(powerComponent) >= 0) {
464:                    throw new PolicyXmlException(id + " is specified more than once in |"
465:                            + TAG_COMPONENT + "| tag");
466:                }
467:                String state = getText(parser);
468:                switch (state) {
469:                    case POWER_ONOFF_ON:
470:                        components.put(powerComponent, true);
471:                        break;
472:                    case POWER_ONOFF_OFF:
473:                        components.put(powerComponent, false);
474:                        break;
475:                    default:
476:                        throw new PolicyXmlException("target state(" + state + ") for " + id
477:                                + " is not valid");
478:                }
479:                skip(parser);
480:            } else if (TAG_OTHER_COMPONENTS.equals(parser.getName())) {
481:                if (!includeOtherComponents) {
482:                    throw new PolicyXmlException("|" + TAG_OTHER_COMPONENTS
483:                            + "| tag is not expected");
484:                }
485:                if (otherComponentsProcessed) {
486:                    throw new PolicyXmlException("more than one |" + TAG_OTHER_COMPONENTS
487:                            + "| tag");
488:                }
489:                otherComponentsProcessed = true;
490:                behavior = parser.getAttributeValue(NAMESPACE, ATTR_BEHAVIOR);
620:    }
