622:    private void addComponent(List<Integer> components, int component) {
623:        int index = components.lastIndexOf(component);
624:        if (index == -1) {
625:            components.add(component);
626:        }
627:    }
628:
629:    private String getText(XmlPullParser parser) throws PolicyXmlException, XmlPullParserException,
630:            IOException {
631:        if (parser.getEventType() != START_TAG) {
632:            throw new PolicyXmlException("tag pair doesn't match");
633:        }
634:        parser.next();
635:        if (parser.getEventType() != TEXT) {
636:            throw new PolicyXmlException("tag value is not found");
637:        }
638:        return parser.getText();
639:    }
640:
641:    private void skip(XmlPullParser parser) throws PolicyXmlException, XmlPullParserException,
642:            IOException {
643:        int type = parser.getEventType();
644:        if (type != START_TAG && type != TEXT) {
645:            throw new PolicyXmlException("tag pair doesn't match");
646:        }
647:        int depth = 1;
648:        while (depth != 0) {
649:            switch (parser.next()) {
650:                case END_TAG:
651:                    depth--;
652:                    break;
653:                case START_TAG:
654:                    depth++;
655:                    break;
656:            }
657:        }
658:    }
