660:    void checkSystemPowerPolicyComponents(int[] components, Set<Integer> visited) throws
661:            PolicyXmlException {
662:        for (int i = 0; i < components.length; i++) {
663:            int component = components[i];
664:            if (!isOverridableComponent(component)) {
665:                throw new PolicyXmlException("Power component(" + powerComponentToString(component)
666:                        + ") cannot be overridden");
667:            }
668:            if (visited.contains(component)) {
669:                throw new PolicyXmlException("Power component(" + powerComponentToString(component)
670:                        + ") is specified more than once");
671:            }
672:            visited.add(component);
673:        }
674:    }
