695:    @PolicyOperationStatus.ErrorCode
696:    int parseComponents(String[] componentArr, boolean enabled, SparseBooleanArray components) {
697:        for (int i = 0; i < componentArr.length; i++) {
698:            int component = toPowerComponent(componentArr[i], false);
699:            if (component == INVALID_POWER_COMPONENT) {
700:                int error = PolicyOperationStatus.ERROR_INVALID_POWER_COMPONENT;
701:                Slogf.w(TAG, PolicyOperationStatus.errorCodeToString(error, componentArr[i]));
702:                return error;
703:            }
704:            if (components.indexOfKey(component) >= 0) {
705:                int error = PolicyOperationStatus.ERROR_DUPLICATED_POWER_COMPONENT;
706:                Slogf.w(TAG, PolicyOperationStatus.errorCodeToString(error, componentArr[i]));
707:                return error;
708:            }
709:            components.put(component, enabled);
710:        }
711:        return PolicyOperationStatus.OK;
712:    }
