41:/**
42: * Class to handle Silent Mode and Non-Silent Mode.
43: *
44: * <p>This monitors {@code /sys/power/pm_silentmode_hw_state} to figure out when to switch to Silent
45: * Mode and updates {@code /sys/power/pm_silentmode_kernel_state} to tell early-init services about
46: * Silent Mode change. Also, it handles forced Silent Mode for testing purpose, which is given
47: * through reboot reason.
48: */
49:final class SilentModeHandler {
50:    static final String SILENT_MODE_FORCED_SILENT = "forced-silent";
51:    static final String SILENT_MODE_FORCED_NON_SILENT = "forced-non-silent";
52:    static final String SILENT_MODE_NON_FORCED = "non-forced-silent-mode";
53:
54:    private static final String TAG = CarLog.tagFor(SilentModeHandler.class);
55:
56:    private static final String SYSFS_FILENAME_HW_STATE_MONITORING =
57:            "/sys/power/pm_silentmode_hw_state";
58:    private static final String SYSFS_FILENAME_KERNEL_SILENTMODE =
59:            "/sys/power/pm_silentmode_kernel_state";
60:    private static final String VALUE_SILENT_MODE = "1";
61:    private static final String VALUE_NON_SILENT_MODE = "0";
62:    private static final String SYSTEM_BOOT_REASON = "sys.boot.reason";
63:    private static final String FORCED_NON_SILENT = "reboot,forcednonsilent";
64:    private static final String FORCED_SILENT = "reboot,forcedsilent";
65:
66:    private final Object mLock = new Object();
67:    private final CarPowerManagementService mService;
68:    private final String mHwStateMonitoringFileName;
69:    private final String mKernelSilentModeFileName;
70:
71:    @GuardedBy("mLock")
72:    private FileObserver mFileObserver;
73:    @GuardedBy("mLock")
74:    private boolean mSilentModeByHwState;
75:    @GuardedBy("mLock")
76:    private boolean mForcedMode;
77:
78:    @VisibleForTesting
79:    SilentModeHandler(@NonNull CarPowerManagementService service,
80:            @Nullable String hwStateMonitoringFileName, @Nullable String kernelSilentModeFileName,
81:            @Nullable String bootReason) {
82:        Objects.requireNonNull(service, "CarPowerManagementService must not be null");
83:        mService = service;
84:        mHwStateMonitoringFileName = hwStateMonitoringFileName == null
85:                ? SYSFS_FILENAME_HW_STATE_MONITORING
86:                : hwStateMonitoringFileName;
87:        mKernelSilentModeFileName = kernelSilentModeFileName == null
88:                ? SYSFS_FILENAME_KERNEL_SILENTMODE
89:                : kernelSilentModeFileName;
90:        if (bootReason == null) {
91:            bootReason = SystemProperties.get(SYSTEM_BOOT_REASON);
92:        }
93:        switch (bootReason) {
94:            case FORCED_SILENT:
95:                Slogf.i(TAG, "Starting in forced silent mode");
96:                mForcedMode = true;
97:                mSilentModeByHwState = true;
98:                break;
99:            case FORCED_NON_SILENT:
100:                Slogf.i(TAG, "Starting in forced non-silent mode");
101:                mForcedMode = true;
102:                mSilentModeByHwState = false;
103:                break;
104:            default:
105:                mForcedMode = false;
106:        }
107:    }
108:
109:    void init() {
110:        boolean forcedMode;
111:        boolean silentMode;
112:        synchronized (mLock) {
113:            forcedMode = mForcedMode;
114:            silentMode = mSilentModeByHwState;
115:        }
116:        if (forcedMode) {
117:            updateKernelSilentMode(silentMode);
118:            mService.notifySilentModeChange(silentMode);
119:            Slogf.i(TAG, "Now in forced mode: monitoring %s is disabled",
120:                    mHwStateMonitoringFileName);
121:        } else {
122:            startMonitoringSilentModeHwState();
123:        }
124:    }
125:
126:    void release() {
127:        synchronized (mLock) {
128:            stopMonitoringSilentModeHwStateLocked();
129:        }
130:    }
131:
132:    @ExcludeFromCodeCoverageGeneratedReport(reason = DUMP_INFO)
133:    void dump(IndentingPrintWriter writer) {
134:        synchronized (mLock) {
135:            writer.printf("Monitoring HW state signal: %b\n", mFileObserver != null);
136:            writer.printf("Silent mode by HW state signal: %b\n", mSilentModeByHwState);
137:            writer.printf("Forced silent mode: %b\n", mForcedMode);
138:        }
139:    }
140:
141:    boolean isSilentMode() {
142:        synchronized (mLock) {
143:            return mSilentModeByHwState;
144:        }
145:    }
146:
147:    void querySilentModeHwState() {
148:        FileObserver fileObserver;
149:        synchronized (mLock) {
150:            fileObserver = mFileObserver;
151:        }
152:        if (fileObserver != null) {
153:            fileObserver.onEvent(FileObserver.MODIFY, mHwStateMonitoringFileName);
154:        }
155:    }
156:
157:    void updateKernelSilentMode(boolean silent) {
158:        try (BufferedWriter writer =
159:                new BufferedWriter(new FileWriter(mKernelSilentModeFileName))) {
160:            String value = silent ? VALUE_SILENT_MODE : VALUE_NON_SILENT_MODE;
161:            writer.write(value);
162:            writer.flush();
163:            Slogf.i(TAG, "%s is updated to %s", mKernelSilentModeFileName, value);
164:        } catch (IOException e) {
165:            Slogf.w(TAG, "Failed to update %s to %s", mKernelSilentModeFileName,
166:                    silent ? VALUE_SILENT_MODE : VALUE_NON_SILENT_MODE);
167:        }
168:    }
169:
170:    void setSilentMode(String silentMode) {
171:        switch (silentMode) {
172:            case SILENT_MODE_FORCED_SILENT:
173:                switchToForcedMode(true);
174:                break;
175:            case SILENT_MODE_FORCED_NON_SILENT:
176:                switchToForcedMode(false);
177:                break;
178:            case SILENT_MODE_NON_FORCED:
179:                switchToNonForcedMode();
180:                break;
181:            default:
182:                Slogf.w(TAG, "Unsupported silent mode: %s", silentMode);
183:        }
184:    }
185:
186:    private void switchToForcedMode(boolean silentMode) {
187:        boolean updated = false;
188:        synchronized (mLock) {
189:            if (!mForcedMode) {
190:                stopMonitoringSilentModeHwStateLocked();
191:                mForcedMode = true;
192:            }
193:            if (mSilentModeByHwState != silentMode) {
194:                mSilentModeByHwState = silentMode;
195:                updated = true;
196:            }
197:        }
198:        if (updated) {
199:            updateKernelSilentMode(silentMode);
200:            mService.notifySilentModeChange(silentMode);
201:        }
202:        Slogf.i(TAG, "Now in forced %s mode: monitoring %s is disabled",
203:                silentMode ? "silent" : "non-silent", mHwStateMonitoringFileName);
204:    }
205:
206:    private void switchToNonForcedMode() {
207:        boolean updated = false;
208:        synchronized (mLock) {
209:            if (mForcedMode) {
210:                Slogf.i(TAG, "Now in non forced mode: monitoring %s is started",
211:                        mHwStateMonitoringFileName);
212:                mForcedMode = false;
213:                updated = true;
214:            }
215:        }
216:        if (updated) {
217:            startMonitoringSilentModeHwState();
218:        }
219:    }
220:
221:    private void startMonitoringSilentModeHwState() {
222:        File monitorFile = new File(mHwStateMonitoringFileName);
223:        if (!monitorFile.exists()) {
224:            Slogf.w(TAG, "Failed to start monitoring Silent Mode HW state: %s doesn't exist",
225:                    mHwStateMonitoringFileName);
226:            return;
227:        }
228:        FileObserver fileObserver = new FileObserver(monitorFile, FileObserver.MODIFY) {
229:            @Override
230:            public void onEvent(int event, String filename) {
231:                boolean newSilentMode;
232:                boolean oldSilentMode;
233:                synchronized (mLock) {
234:                    // FileObserver can report events even after stopWatching is called. To ignore
235:                    // such events, check the current internal state.
236:                    if (mForcedMode) {
237:                        return;
238:                    }
239:                    oldSilentMode = mSilentModeByHwState;
240:                    try {
241:                        String contents = IoUtils.readFileAsString(mHwStateMonitoringFileName)
242:                                .trim();
243:                        mSilentModeByHwState = VALUE_SILENT_MODE.equals(contents);
244:                        Slogf.i(TAG, "%s indicates %s mode", mHwStateMonitoringFileName,
245:                                mSilentModeByHwState ? "silent" : "non-silent");
246:                    } catch (Exception e) {
247:                        Slogf.w(TAG, e, "Failed to read %s", mHwStateMonitoringFileName);
248:                        return;
249:                    }
250:                    newSilentMode = mSilentModeByHwState;
251:                }
252:                if (newSilentMode != oldSilentMode) {
253:                    updateKernelSilentMode(newSilentMode);
254:                    mService.notifySilentModeChange(newSilentMode);
255:                }
256:            }
257:        };
258:        synchronized (mLock) {
259:            mFileObserver = fileObserver;
260:        }
261:        fileObserver.startWatching();
262:        // Trigger the observer to get the initial contents
263:        querySilentModeHwState();
264:    }
265:
266:    @GuardedBy("mLock")
267:    private void stopMonitoringSilentModeHwStateLocked() {
268:        if (mFileObserver != null) {
269:            mFileObserver.stopWatching();
270:            mFileObserver = null;
271:        }
272:    }
273:}
