707:    private void setServiceForListenerLocked(boolean useCompletion) {
708:        if (mListenerToService == null) {
709:            ICarPowerStateListener listenerToService = new ICarPowerStateListener.Stub() {
710:                @Override
711:                public void onStateChanged(int state, long expirationTimeMs)
712:                        throws RemoteException {
713:                    if (useCompletion) {
714:                        CarPowerStateListenerWithCompletion listenerWithCompletion;
715:                        CompletablePowerStateChangeFuture future;
716:                        Executor executor;
717:                        synchronized (mLock) {
718:                            // Updates CompletablePowerStateChangeFuture. This will recreate it or
719:                            // just clean it up.
720:                            updateFutureLocked(state, expirationTimeMs);
721:                            listenerWithCompletion = mListenerWithCompletion;
722:                            future = mFuture;
723:                            executor = mExecutor;
724:                        }
725:                        // Notifies the user that the state has changed and supply a future.
726:                        if (listenerWithCompletion != null && executor != null) {
727:                            executor.execute(
728:                                    () -> listenerWithCompletion.onStateChanged(state, future));
729:                        }
730:                    } else {
731:                        CarPowerStateListener listener;
732:                        Executor executor;
733:                        synchronized (mLock) {
734:                            listener = mListener;
735:                            executor = mExecutor;
736:                        }
737:                        // Notifies the user without supplying a future.
738:                        if (listener != null && executor != null) {
739:                            executor.execute(() -> listener.onStateChanged(state));
740:                        }
741:                    }
742:                }
743:            };
744:            try {
745:                if (useCompletion) {
746:                    mService.registerListenerWithCompletion(listenerToService);
747:                } else {
748:                    mService.registerListener(listenerToService);
749:                }
750:                mListenerToService = listenerToService;
751:            } catch (RemoteException e) {
752:                handleRemoteExceptionFromCarService(e);
753:            }
754:        }
755:    }
