757:    @GuardedBy("mLock")
758:    private void updateFutureLocked(@CarPowerState int state, long expirationTimeMs) {
759:        cleanupFutureLocked();
760:        if (isCompletionAllowed(state)) {
761:            // Creates a CompletablePowerStateChangeFuture and passes it to the listener.
762:            // When the listener completes, tells CarPowerManagementService that this action is
763:            // finished.
764:            mFuture = new CompletablePowerStateChangeFutureImpl(() -> {
765:                ICarPowerStateListener listenerToService;
766:                synchronized (mLock) {
767:                    listenerToService = mListenerToService;
768:                }
769:                try {
770:                    mService.finished(state, listenerToService);
771:                } catch (RemoteException e) {
772:                    handleRemoteExceptionFromCarService(e);
773:                }
774:            }, expirationTimeMs);
775:        }
776:    }
