138:PowerComponent toPowerComponent(std::string_view id, std::string_view prefix) {
139:    if (!StartsWith(id, prefix)) {
140:        return INVALID_POWER_COMPONENT;
141:    }
142:    std::string_view componentId = id.substr(prefix.size());
143:    PowerComponent matchedComponent = INVALID_POWER_COMPONENT;
144:    iterateAllPowerComponents([componentId, &matchedComponent](PowerComponent component) -> bool {
145:        if (componentId == toString(component)) {
146:            matchedComponent = component;
147:            return false;
148:        }
149:        return true;
150:    });
151:    return matchedComponent;
152:}
