176:Result<void> readComponents(const XMLElement* pPolicy, CarPowerPolicyPtr policy,
177:                            std::unordered_set<PowerComponent>* visited) {
178:    for (const XMLElement* pComponent = pPolicy->FirstChildElement(kTagComponent);
179:         pComponent != nullptr; pComponent = pComponent->NextSiblingElement(kTagComponent)) {
180:        const char* id;
181:        if (pComponent->QueryStringAttribute(kAttrId, &id) != XML_SUCCESS) {
182:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrId,
183:                                           kTagComponent);
184:        }
185:        PowerComponent componentId = toPowerComponent(id, kPowerComponentPrefix);
186:        if (componentId == INVALID_POWER_COMPONENT) {
187:            return Error() << StringPrintf("XML configuration has invalid value(%s) in |%s| "
188:                                           "attribute of |%s| tag",
189:                                           safePtrPrint(id), kAttrId, kTagComponent);
190:        }
191:        if (visited->count(componentId) > 0) {
192:            return Error() << StringPrintf("XML configuration has duplicated component(%s) in |%s| "
193:                                           "attribute of |%s| tag",
194:                                           toString(componentId).c_str(), kAttrId, kTagComponent);
195:        }
196:        visited->insert(componentId);
197:        const char* powerState = pComponent->GetText();
198:        if (!strcmp(powerState, kPowerStateOn)) {
199:            policy->enabledComponents.push_back(componentId);
200:        } else if (!strcmp(powerState, kPowerStateOff)) {
201:            policy->disabledComponents.push_back(componentId);
202:        } else {
203:            return Error() << StringPrintf("XML configuration has invalid value(%s) in |%s| tag",
204:                                           safePtrPrint(powerState), kTagComponent);
205:        }
206:    }
207:    return {};
208:}
