210:Result<void> readOtherComponents(const XMLElement* pPolicy, CarPowerPolicyPtr policy,
211:                                 const std::unordered_set<PowerComponent>& visited) {
212:    const char* otherComponentBehavior = kPowerStateUntouched;
213:    const XMLElement* pElement = pPolicy->FirstChildElement(kTagOtherComponents);
214:    if (pElement != nullptr) {
215:        if (pElement->QueryStringAttribute(kAttrBehavior, &otherComponentBehavior) != XML_SUCCESS) {
216:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag",
217:                                           kAttrBehavior, kTagOtherComponents);
218:        }
219:    }
220:    if (!strcmp(otherComponentBehavior, kPowerStateOn)) {
221:        iterateAllPowerComponents([&visited, &policy](PowerComponent component) -> bool {
222:            if (visited.count(component) == 0) {
223:                policy->enabledComponents.push_back(component);
224:            }
225:            return true;
226:        });
227:    } else if (!strcmp(otherComponentBehavior, kPowerStateOff)) {
228:        iterateAllPowerComponents([&visited, &policy](PowerComponent component) -> bool {
229:            if (visited.count(component) == 0) {
230:                policy->disabledComponents.push_back(component);
231:            }
232:            return true;
233:        });
234:    } else if (!strcmp(otherComponentBehavior, kPowerStateUntouched)) {
235:        // Do nothing
236:    } else {
237:        return Error() << StringPrintf("XML configuration has invalid value(%s) in |%s| attribute "
238:                                       "of |%s| tag",
239:                                       safePtrPrint(otherComponentBehavior), kAttrBehavior,
240:                                       kTagOtherComponents);
241:    }
242:    return {};
243:}
