245:Result<std::vector<CarPowerPolicyPtr>> readPolicies(const XMLElement* pRoot, const char* tag,
246:                                                    bool includeOtherComponents) {
247:    std::vector<CarPowerPolicyPtr> policies;
248:    const XMLElement* pPolicies = pRoot->FirstChildElement(tag);
249:    if (pPolicies == nullptr) {
250:        return std::vector<CarPowerPolicyPtr>();
251:    }
252:    for (const XMLElement* pPolicy = pPolicies->FirstChildElement(kTagPolicy); pPolicy != nullptr;
253:         pPolicy = pPolicy->NextSiblingElement(kTagPolicy)) {
254:        std::unordered_set<PowerComponent> visited;
255:        const char* policyId;
256:        if (pPolicy->QueryStringAttribute(kAttrId, &policyId) != XML_SUCCESS) {
257:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrId,
258:                                           kTagPolicy);
259:        }
260:        if (includeOtherComponents && isSystemPowerPolicy(policyId)) {
261:            return Error() << "Policy ID should not start with \"system_power_policy_\"";
262:        }
263:        auto policy = std::make_shared<CarPowerPolicy>();
264:        policy->policyId = policyId;
265:
266:        auto ret = readComponents(pPolicy, policy, &visited);
267:        if (!ret.ok()) {
268:            return ret.error();
269:        }
270:        if (includeOtherComponents) {
271:            ret = readOtherComponents(pPolicy, policy, visited);
272:            if (!ret.ok()) {
273:                return ret.error();
274:            }
275:        }
276:        policies.push_back(policy);
277:    }
278:    return policies;
279:}
