281:Result<PolicyGroup> readPolicyGroup(
282:        const XMLElement* pPolicyGroup,
283:        const std::unordered_map<std::string, CarPowerPolicyPtr>& registeredPowerPolicies) {
284:    PolicyGroup policyGroup;
285:    for (const XMLElement* pDefaultPolicy = pPolicyGroup->FirstChildElement(kTagDefaultPolicy);
286:         pDefaultPolicy != nullptr;
287:         pDefaultPolicy = pDefaultPolicy->NextSiblingElement(kTagDefaultPolicy)) {
288:        const char* state;
289:        if (pDefaultPolicy->QueryStringAttribute(kAttrState, &state) != XML_SUCCESS) {
290:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrState,
291:                                           kTagDefaultPolicy);
292:        }
293:        int32_t powerState = toVehiclePowerState(state);
294:        if (!isValidPowerState(powerState)) {
295:            return Error() << StringPrintf("Target state(%s) is not valid", state);
296:        }
297:        const char* policyId;
298:        if (pDefaultPolicy->QueryStringAttribute(kAttrId, &policyId) != XML_SUCCESS) {
299:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrId,
300:                                           kTagDefaultPolicy);
301:        }
302:        if (registeredPowerPolicies.count(policyId) == 0) {
303:            return Error() << StringPrintf("Policy(id: %s) is not registered", policyId);
304:        }
305:        policyGroup.emplace(powerState, policyId);
306:    }
307:    for (const XMLElement* pNoPolicy = pPolicyGroup->FirstChildElement(kTagNoDefaultPolicy);
308:         pNoPolicy != nullptr; pNoPolicy = pNoPolicy->NextSiblingElement(kTagNoDefaultPolicy)) {
309:        const char* state;
310:        if (pNoPolicy->QueryStringAttribute(kAttrState, &state) != XML_SUCCESS) {
311:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrState,
312:                                           kTagNoDefaultPolicy);
313:        }
314:        int32_t powerState = toVehiclePowerState(state);
315:        if (!isValidPowerState(powerState)) {
316:            return Error() << StringPrintf("Target state(%s) is not valid", state);
317:        }
318:        if (policyGroup.count(powerState) > 0) {
319:            return Error()
320:                    << StringPrintf("Target state(%s) is specified both in |%s| and |%s| tags",
321:                                    state, kTagDefaultPolicy, kTagNoDefaultPolicy);
322:        }
323:    }
324:    return policyGroup;
325:}
