327:Result<std::unordered_map<std::string, PolicyGroup>> readPolicyGroups(
328:        const XMLElement* pRoot,
329:        const std::unordered_map<std::string, CarPowerPolicyPtr>& registeredPowerPolicies) {
330:    const XMLElement* pPolicyGroups = pRoot->FirstChildElement(kTagPolicyGroups);
331:    if (pPolicyGroups == nullptr) {
332:        return std::unordered_map<std::string, PolicyGroup>();
333:    }
334:    std::unordered_map<std::string, PolicyGroup> policyGroups;
335:
336:    for (const XMLElement* pPolicyGroup = pPolicyGroups->FirstChildElement(kTagPolicyGroup);
337:         pPolicyGroup != nullptr;
338:         pPolicyGroup = pPolicyGroup->NextSiblingElement(kTagPolicyGroup)) {
339:        const char* policyGroupId;
340:        if (pPolicyGroup->QueryStringAttribute(kAttrId, &policyGroupId) != XML_SUCCESS) {
341:            return Error() << StringPrintf("Failed to read |%s| attribute in |%s| tag", kAttrId,
342:                                           kTagPolicyGroup);
343:        }
344:        const auto& policyGroup = readPolicyGroup(pPolicyGroup, registeredPowerPolicies);
345:        if (!policyGroup.ok()) {
346:            return Error() << policyGroup.error();
347:        }
348:        policyGroups.emplace(policyGroupId, *policyGroup);
349:    }
350:    return policyGroups;
351:}
