392:                         std::vector<PowerComponent>* componentsAddedTo,
393:                         std::vector<PowerComponent>* componentsRemovedFrom) {
394:    for (const auto component : configComponents) {
395:        auto it = std::find(componentsAddedTo->begin(), componentsAddedTo->end(), component);
396:        if (it == componentsAddedTo->end()) {
397:            componentsAddedTo->push_back(component);
398:        }
399:        it = std::find(componentsRemovedFrom->begin(), componentsRemovedFrom->end(), component);
400:        if (it != componentsRemovedFrom->end()) {
401:            componentsRemovedFrom->erase(it);
402:        }
403:    }
404:}
