46:void PowerComponentHandler::applyPowerPolicy(const CarPowerPolicyPtr& powerPolicy) {
47:    Mutex::Autolock lock(mMutex);
48:    std::unordered_map<PowerComponent, bool> componentStates;
49:    mAccumulatedPolicy->policyId = powerPolicy->policyId;
50:    for (const auto component : mAccumulatedPolicy->enabledComponents) {
51:        componentStates[component] = true;
52:    }
53:    for (const auto component : mAccumulatedPolicy->disabledComponents) {
54:        componentStates[component] = false;
55:    }
56:    for (const auto component : powerPolicy->enabledComponents) {
57:        componentStates[component] = true;
58:    }
59:    for (const auto component : powerPolicy->disabledComponents) {
60:        componentStates[component] = false;
61:    }
62:    mAccumulatedPolicy->enabledComponents.clear();
63:    mAccumulatedPolicy->disabledComponents.clear();
64:    for (const auto [component, state] : componentStates) {
65:        if (state) {
66:            mAccumulatedPolicy->enabledComponents.push_back(component);
67:        } else {
68:            mAccumulatedPolicy->disabledComponents.push_back(component);
69:        }
70:    }
71:}
