142:bool compareComponents(const std::vector<PowerComponent>& a, const std::vector<PowerComponent>& b) {
143:    int lenA = a.size();
144:    int lenB = b.size();
145:    if (lenA != lenB) {
146:        return false;
147:    }
148:    std::unordered_set<PowerComponent> componentSet;
149:    for (const auto component : a) {
150:        componentSet.insert(component);
151:    }
152:    for (const auto component : b) {
153:        if (componentSet.count(component) == 0) {
154:            return false;
155:        }
156:        componentSet.erase(component);
157:    }
158:    return componentSet.size() == 0;
159:}
160:
161:bool isEqual(const CarPowerPolicy& a, const CarPowerPolicy& b) {
162:    return a.policyId == a.policyId &&
163:            compareComponents(a.enabledComponents, b.enabledComponents) &&
164:            compareComponents(a.disabledComponents, b.disabledComponents);
165:}
