246:        }
247:
248:        @Override
249:        public void onPropertyEvent(
250:                ArrayList<android.hardware.automotive.vehicle.V2_0.VehiclePropValue> propValues) {
251:            ArrayList<HalPropValue> values = new ArrayList<>();
252:            for (android.hardware.automotive.vehicle.V2_0.VehiclePropValue value : propValues) {
253:                values.add(mBuilder.build(value));
254:            }
255:            mCallback.onPropertyEvent(values);
256:        }
257:
258:        @Override
259:        public void onPropertySet(
260:                android.hardware.automotive.vehicle.V2_0.VehiclePropValue propValue) {
261:            // Deprecated, do nothing.
262:        }
263:
264:        @Override
265:        public void onPropertySetError(int errorCode, int propId, int areaId) {
266:            VehiclePropError error = new VehiclePropError();
267:            error.propId = propId;
268:            error.areaId = areaId;
269:            error.errorCode = errorCode;
270:            ArrayList<VehiclePropError> errors = new ArrayList<VehiclePropError>();
271:            errors.add(error);
272:            mCallback.onPropertySetError(errors);
273:        }
274:
275:        @Override
276:        public void subscribe(SubscribeOptions[] options) throws RemoteException {
277:            ArrayList<android.hardware.automotive.vehicle.V2_0.SubscribeOptions> hidlOptions =
278:                    new ArrayList<>();
279:            for (SubscribeOptions option : options) {
280:                hidlOptions.add(subscribeOptionsToHidl(option));
