282:            mHidlVehicle.subscribe(this, hidlOptions);
283:        }
284:
285:        @Override
286:        public void unsubscribe(int prop) throws RemoteException {
287:            mHidlVehicle.unsubscribe(this, prop);
288:        }
289:    }
