25:/**
26: * Factory for constructing wrappers around IAudioControl HAL instances.
27: */
28:public final class AudioControlFactory {
29:
30:    @VisibleForTesting
31:    static final String TAG = CarLog.tagFor(AudioControlFactory.class);
32:
33:    private AudioControlFactory() {
34:    }
35:
36:    /**
37:     * Generates {@link AudioControlWrapper} for interacting with IAudioControl HAL service. The HAL
38:     * version priority is: Current AIDL, HIDL V2, HIDL V1. The wrapper will try to fetch the
39:     * highest priority service, and then fall back to older versions if it's not available. The
40:     * wrapper will throw if none is registered on the manifest.
41:     *
42:     * @return {@link AudioControlWrapper} for registered IAudioControl service.
43:     */
44:    public static AudioControlWrapper newAudioControl() {
45:        IBinder binder = AudioControlWrapperAidl.getService();
46:        if (binder != null) {
47:            return new AudioControlWrapperAidl(binder);
48:        }
49:        Slogf.i(TAG, "AIDL AudioControl HAL not in the manifest");
50:
51:        android.hardware.automotive.audiocontrol.V2_0.IAudioControl audioControlV2 =
52:                AudioControlWrapperV2.getService();
53:        if (audioControlV2 != null) {
54:            return new AudioControlWrapperV2(audioControlV2);
55:        }
56:        Slogf.i(TAG, "HIDL AudioControl@V2.0 not in the manifest");
57:
58:        android.hardware.automotive.audiocontrol.V1_0.IAudioControl audioControlV1 =
59:                AudioControlWrapperV1.getService();
60:        if (audioControlV1 != null) {
61:            Slogf.w(TAG, "HIDL AudioControl V1.0 is deprecated. Consider upgrading to AIDL");
62:            return new AudioControlWrapperV1(audioControlV1);
63:        }
64:
65:        throw new IllegalStateException("No version of AudioControl HAL in the manifest");
66:    }
67:}
