32:int CarPowerManager::clearListener() {
33:    int retVal = -1;
34:
35:    if (mIsConnected && (mListenerToService != nullptr)) {
36:        mICarPower->unregisterListener(mListenerToService);
37:        mListenerToService = nullptr;
38:        retVal = 0;
39:    }
40:    return retVal;
41:}
42:
43:int CarPowerManager::requestShutdownOnNextSuspend() {
44:    int retVal = -1;
45:
46:    if (connectToCarService()) {
47:        mICarPower->requestShutdownOnNextSuspend();
48:        retVal = 0;
49:    }
50:    return retVal;
51:}
