32:int CarPowerManager::clearListener() {
33:    int retVal = -1;
34:
35:    if (mIsConnected && (mListenerToService != nullptr)) {
36:        mICarPower->unregisterListener(mListenerToService);
37:        mListenerToService = nullptr;
38:        retVal = 0;
39:    }
40:    return retVal;
41:}
42:
43:int CarPowerManager::requestShutdownOnNextSuspend() {
44:    int retVal = -1;
45:
46:    if (connectToCarService()) {
47:        mICarPower->requestShutdownOnNextSuspend();
48:        retVal = 0;
49:    }
50:    return retVal;
51:}
52:
53:int CarPowerManager::setListener(Listener listener) {
54:    int retVal = -1;
55:
56:    if (connectToCarService()) {
57:        if (mListenerToService == nullptr) {
58:            mListenerToService = new CarPowerStateListener(this);
59:            mICarPower->registerListener(mListenerToService);
60:        }
61:
62:        // Set the listener
63:        mListener = listener;
64:        retVal = 0;
65:    }
66:    return retVal;
67:}
