71:bool CarPowerManager::connectToCarService() {
72:    if (mIsConnected) {
73:        // Service is already connected
74:        return true;
75:    }
76:
77:    const String16 ICarName("car_service");
78:    const String16 ICarPowerName("power");
79:
80:    ALOGI(LOG_TAG "Connecting to CarService");
81:
82:    // Get ICar
83:    sp<IServiceManager> serviceManager = defaultServiceManager();
84:    if (serviceManager == nullptr) {
85:        ALOGE(LOG_TAG "Cannot get defaultServiceManager");
86:        return(false);
87:    }
88:
89:    sp<IBinder> binder = (serviceManager->getService(ICarName));
90:    if (binder == nullptr) {
91:        ALOGE(LOG_TAG "Cannot get ICar");
92:        return false;
93:    }
94:
95:    // Get ICarPower
96:    sp<ICar> iCar = interface_cast<ICar>(binder);
97:    if (iCar == nullptr) {
98:        ALOGW(LOG_TAG "car service unavailable");
99:        return false;
100:    }
101:
102:    iCar->getCarService(ICarPowerName, &binder);
103:    if (binder == nullptr) {
